# style-gconv1 v3: v1 with the late monolith fallback requiring two allies in sight.
# Top-team data: 0% solo, 29% with 2 attackers, 49% with 3, so the push needs allies_within(4) >= 2
# (three attackers including self). The bot also drops the push as soon as the group thins out.
# Starts at round 900. Everything else is unchanged from v1.

BANK_BAG = 15
BANK_NEAR_BAG = 10
BANK_ETA = 3

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
